{
  "qid": "0005_ISS_L3",
  "sample_id": "0005",
  "gen_prompt": "生成一幅广角写实的国际空间站在地球上空运行的场景图。主体完整可见并占据画面视觉中心，深黑背景延伸至画面上方，远处下方可见弧形的蓝色地球与白色云层，采用自然阳光照明，呈现清晰、真实的航天摄影质感。",
  "invocation": "L3",
  "knowledge_dim": "航天工程与空间设施识别",
  "fidelity_checks": [
    {
      "check": "国际空间站应呈现为由多个相互连接的舱段和外部设备构成的复杂组合体，而不是一艘单一、流线型的整体飞船。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["1"],
        "derivation_chain": "前提：画面主体是国际空间站并处于在轨运行状态→知识：国际空间站是由多个舱段联合建造的长期载人轨道设施→结论：主体应显示多个彼此连接、形态各异的舱段及其组合关系，而非单一整体式飞船"
      },
      "rubric": {
        "tier_0": "主体缺失，或主要呈现为单一整体式飞船，无法辨认出多个相互连接的舱段。",
        "tier_1": "能看到两个或少量相连舱段，但组合关系不完整、结构过度简化，或整体仍明显像单一飞船。",
        "tier_2": "清楚可见多个不同形态的舱段相互连接，形成复杂的轨道设施组合体，整体不是单一整体式飞船。"
      },
      "variants_used": "无变体，覆盖约束[1]全部要求",
      "visibility_requirement": "至少应有主体中部和两处以上连接区域清晰可见；若部分舱段被透视或结构遮挡，只要仍能从可见连接关系确认多舱段组合即可，不因不可见区域扣分。",
      "weight": 1.0
    },
    {
      "check": "国际空间站应具有展开状态的大面积板状太阳能电池阵列，并与站体连接。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["2"],
        "derivation_chain": "前提：画面主体是持续运行的国际空间站→知识：空间站需要通过大型展开式能源系统为长期运行提供电力→结论：站体外侧应出现与主体连接的展开大面积板状太阳能电池阵列"
      },
      "rubric": {
        "tier_0": "完全看不到任何大面积板状阵列，或出现的只是小型装饰板、封闭舱体或其他不具备阵列形态的部件。",
        "tier_1": "能看到一部分板状阵列或少量展开面，但面积、展开状态或与站体的连接关系不够明确。",
        "tier_2": "至少一组清晰可辨的大面积平面阵列处于展开状态，并通过支撑结构与空间站主体相连；由于视角造成的透视变形不影响判定。"
      },
      "variants_used": "无变体，覆盖约束[2]全部要求",
      "visibility_requirement": "至少应有一组阵列的连续板面和连接位置可见；若其他阵列被主体遮挡，不要求全部阵列同时出现。",
      "weight": 1.0
    },
    {
      "check": "站体应具有横向延伸的桁架式主梁，并承担阵列或外部设备的安装支撑作用。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["3"],
        "derivation_chain": "前提：画面主体是国际空间站及其外部设备→知识：空间站采用横向主梁作为大型外部系统的安装骨架→结论：主体应显示横向延伸、由杆件组成的桁架式主梁，并有阵列或设备安装在其上或附近"
      },
      "rubric": {
        "tier_0": "完全没有可辨认的横向梁架，或主体只有封闭舱体，没有杆件构成的支撑骨架。",
        "tier_1": "出现横向杆件或梁架的局部，但桁架结构不连续、方向不明确，或与外部阵列及设备的支撑关系不清楚。",
        "tier_2": "清楚可见横向延伸的开放式桁架主梁，由多根杆件构成立体骨架，并能看出其承载或连接外部阵列、设备的作用。"
      },
      "variants_used": "无变体，覆盖约束[3]全部要求",
      "visibility_requirement": "至少应有一段连续横向桁架及其与外部部件的连接关系可见；局部被阵列或舱段遮挡时，以剩余可见结构判定。",
      "weight": 1.0
    },
    {
      "check": "空间站应悬浮于太空环境中，并与地球表面保持明显的高空空间关系，而不是位于地面、发射台、天体表面或大气云层内部。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["4"],
        "derivation_chain": "前提：画面要求表现国际空间站在地球上空运行→知识：国际空间站运行在近地轨道而非地表或大气层内部→结论：主体应位于黑暗太空背景中自由悬浮，地球弧线和云层只能作为远处背景"
      },
      "rubric": {
        "tier_0": "主体位于地面、发射台、天体表面或云层内部，或完全没有太空背景与高空空间关系。",
        "tier_1": "有黑暗背景或地球背景，但主体与地球表面的距离关系含混，像在大气层中飞行或贴近地表。",
        "tier_2": "主体明确处于黑暗太空中自由悬浮，地球弧线和云层位于远处背景，未与任何地面、平台或天体表面接触。"
      },
      "variants_used": "无变体，覆盖约束[4]全部要求",
      "visibility_requirement": "至少应同时看到主体周围的黑暗空间和一段远处地球弧线或云层背景；若构图裁切导致地球不可见，只要主体与太空背景关系明确，不因地球不可见直接判零。",
      "weight": 1.0
    },
    {
      "check": "主体不得呈现飞机式的机翼、尾翼、螺旋桨或喷气发动机等空气动力学航空器特征。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["5"],
        "derivation_chain": "前提：画面主体是轨道空间设施而非大气层航空器→知识：轨道空间设施不依靠空气动力学翼面或喷气推进器在大气中飞行→结论：主体外形不得出现明确属于飞机的机翼、尾翼、螺旋桨或喷气发动机"
      },
      "rubric": {
        "tier_0": "清楚出现一项或多项飞机式机翼、尾翼、螺旋桨或喷气发动机，并使主体明显变成航空器。",
        "tier_1": "有少量外伸部件可能与航空器部件混淆，但数量少、形态不完整，主体仍主要呈空间设施结构。",
        "tier_2": "未出现明确的机翼、尾翼、螺旋桨或喷气发动机；外伸部件均能保持为设施支架、设备或连接结构的合理形态。"
      },
      "variants_used": "无变体，覆盖约束[5]全部要求",
      "visibility_requirement": "主体外轮廓及主要外伸部件应有足够面积可检查；若某些区域被透视、裁切或遮挡，则仅对可见部分判定，不推断不可见区域。",
      "weight": 1.0
    },
    {
      "check": "主体不得出现轮式起落架、轮胎、地面滑跑装置，或屋顶瓦片、烟囱、住宅门窗等地面建筑构件。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["6"],
        "derivation_chain": "前提：画面表现的是自由运行的轨道设施→知识：轨道设施不需要地面起降和建筑居住构件→结论：主体外部不得出现轮式起落架、轮胎、地面滑跑装置或明确的地面建筑构件"
      },
      "rubric": {
        "tier_0": "清楚出现轮胎、轮式起落架、地面滑跑装置，或明显的屋顶瓦片、烟囱、住宅门窗等建筑构件。",
        "tier_1": "出现少量疑似轮式或建筑化细节，但无法明确归类，且未明显改变主体的空间设施属性。",
        "tier_2": "可见主体区域中没有明确属于地面交通或地面建筑的上述构件，外部部件保持航天设施语义。"
      },
      "variants_used": "无变体，覆盖约束[6]全部要求",
      "visibility_requirement": "至少应有主体外部设备和连接区域可见；不可见或被遮挡的区域不作推断，不因其无法检查而扣分。",
      "weight": 1.0
    },
    {
      "check": "主体及其附近不得出现明确属于其他空间站的名称标识。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["7"],
        "derivation_chain": "前提：题目主体是国际空间站→知识：不同空间站是相互区分的独立设施，其他空间站名称不能作为该主体的身份标识→结论：画面中不得出现明确指向其他空间站的名称标识"
      },
      "rubric": {
        "tier_0": "清晰可读的其他空间站名称标识出现在主体或其显著附近位置。",
        "tier_1": "出现模糊、残缺或不可读的疑似文字标记，无法确认其属于其他空间站。",
        "tier_2": "没有可确认属于其他空间站的名称标识；无文字或不可辨认的微小标记不扣分。"
      },
      "variants_used": "无变体，覆盖约束[7]全部要求",
      "visibility_requirement": "仅检查画面中清晰可辨认的文字或标识；若文字太小、背向镜头或被遮挡而无法读取，不按其他空间站名称处理。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "题面点名的国际空间站应是画面主体，完整可见并占据视觉中心和主要视觉焦点。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "国际空间站缺失、主体跑偏，或仅作为很小的背景物出现。",
        "tier_1": "国际空间站存在且可辨认，但主体占比偏小、被严重裁切或视觉焦点被其他元素夺走。",
        "tier_2": "国际空间站完整呈现，占据画面中心及主要面积，成为最醒目的视觉主体。"
      }
    },
    {
      "check": "题面要求的地球弧线与白色云层应位于主体下方的远处背景，黑色太空背景应位于画面上方和周围。",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "地球背景位于主体上方或包围关系完全错误，或黑色太空背景基本缺失。",
        "tier_1": "大致出现地球在下方、太空在上方的布局，但位置关系不稳定、比例失衡或背景元素不清楚。",
        "tier_2": "清楚呈现主体上方及周围的深黑太空背景，弧形地球和白色云层位于主体下方远处，空间层次符合题面。"
      }
    },
    {
      "check": "场景类型应是国际空间站在地球上空运行的写实太空场景，而不是地面、室内或普通航空摄影场景。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "场景明显变成地面、室内、发射场或与题面无关的普通飞行环境。",
        "tier_1": "基本具有太空场景特征，但地球背景、黑暗空间或在轨运行关系表现含混。",
        "tier_2": "明确呈现写实的地球上空太空环境，空间站与地球、黑暗背景之间的关系自然可信。"
      }
    }
  ],
  "quality_facets": [
    "physical_logic",
    "material_texture",
    "edge_clarity",
    "resolution"
  ],
  "aesthetic_facets": [
    "composition",
    "color_harmony",
    "lighting_atmosphere"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "3",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "4",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "5",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "6",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "7",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "题面未限定空间站的具体朝向、阵列数量或舱段布局，以保留合法视角和构型差异；对被透视、裁切或遮挡的局部结构按各条visibility_requirement处理。"
}
